//! The export pipeline: build the model crate with the sidecar
//! enabled, harvest the JSON, emit the generated tree (capi crate,
//! C++ header, vendored math headers). `check` regenerates in memory
//! and diffs against the committed tree.

use crate::ir::Model;
use std::path::{Path, PathBuf};

const MARKER: &str = "GENERATED by cargo-arael";
const STUB_NOTE: &str = "placeholder until the export completes";

/// What `run_export` does with one generated file, given the file's
/// tree-relative path, what is on disk (`None` = absent) and the new
/// content.
///
/// Scaffold files (`capi/Cargo.toml`) are written ONCE: a user may
/// edit them (dependencies, crate-type, profile), so an existing one
/// is kept unless it is still the pre-harvest stub -- delete the file
/// to regenerate. Everything else overwrites its own marker-stamped
/// output and refuses a file that does not look generated. A file
/// whose content is already the new content is left untouched, so an
/// export that changes nothing moves no timestamp and the consumer's
/// build has nothing to redo.
#[derive(Debug, PartialEq, Eq)]
pub enum WriteAction {
    Write,
    Keep,
    Refuse,
    Unchanged,
}

pub fn write_action(rel: &Path, on_disk: Option<&str>, content: &str) -> WriteAction {
    let scaffold = rel == Path::new("capi/Cargo.toml");
    match on_disk {
        None => WriteAction::Write,
        Some(old) if scaffold => {
            if old.contains(STUB_NOTE) { WriteAction::Write } else { WriteAction::Keep }
        }
        Some(old) if old == content => WriteAction::Unchanged,
        Some(old) => {
            if old.contains(MARKER) { WriteAction::Write } else { WriteAction::Refuse }
        }
    }
}

